static const agc_dp coefficient[8]={{013240,023630},{074721,047775},{02440,020237},{075067,070742},{03436,026756},{074037,057640},{03046,07143},{076654,042244}};
static agc_word variant(enum inverse_trig_mission mission,agc_word lm,agc_word cm){return mission==INVERSE_TRIG_LM?lm:cm;}
static uint8_t valid(const apollo_overlay_state *m,enum inverse_trig_mission mission){return (uint8_t)((mission==INVERSE_TRIG_LM||mission==INVERSE_TRIG_CM)&&m->words[7]==0&&m->words[3]<=03400u&&(m->words[3]&0377u)==0&&m->words[4]==0&&m->words[6]==(m->words[3]>>8)&&m->words[0163]<=077777u);}
static uint8_t continuation(const apollo_overlay_state *m,enum inverse_trig_mission mission){agc_word e=m->words[0136];return (uint8_t)(valid(m,mission)&&(e==variant(mission,016061,016030)||e==variant(mission,013707,013706)||(e==variant(mission,013702,013701)&&(m->words[0137]==variant(mission,016061,016030)||m->words[0137]==variant(mission,013707,013706)))));}
static void subtract_from(apollo_overlay_state *m,agc_word bound){agc_register a=agc_add_register(agc_extend(agc_negate(m->words[0154])),agc_extend(bound));agc_register l=agc_extend(agc_negate(m->words[0155]));m->words[0]=agc_extend(m->words[0154]);m->words[1]=agc_extend(m->words[0155]);m->words[0154]=agc_correct(a);m->words[0155]=agc_correct(l);}
static void epilogue(apollo_overlay_state *m,enum inverse_trig_mission mission,agc_word q){agc_word escape=m->words[0136];m->words[2]=q;if(escape==variant(mission,013702,013701)){subtract_from(m,020000);escape=m->words[0137];m->words[2]=variant(mission,03707,03706);}if(escape==variant(mission,013707,013706))subtract_from(m,010000);m->words[5]=variant(mission,06061,06030);}
static void zero_answer(apollo_overlay_state *m,enum inverse_trig_mission mission,agc_word a,uint8_t minor){if(minor)m->words[0155]=a;m->words[0154]=a;m->words[0]=agc_extend(a);epilogue(m,mission,variant(mission,03642,03641));}
enum inverse_trig_status inverse_trig_prepare(apollo_overlay_state *m,enum inverse_trig_mission mission,uint8_t arcsine){agc_register a;agc_word original_high,original_low;enum agc_ccs_class cl;int sign=0;uint8_t i;if(!valid(m,mission)||arcsine>1u||m->words[5]!=(arcsine?variant(mission,03610,03607):variant(mission,03612,03611)))return INVERSE_TRIG_OUT_OF_SCOPE;m->words[1]=agc_extend(agc_correct(m->words[1]));m->words[0136]=arcsine?variant(mission,013707,013706):variant(mission,016061,016030);for(i=0;i<3u;++i){sign=agc_to_int(m->words[0154u+i]);if(sign)break;}if(!sign){zero_answer(m,mission,010000,0);return INVERSE_TRIG_DONE;}if(sign<0){m->words[1]=agc_extend(m->words[0155]);m->words[0154]=agc_negate(m->words[0154]);m->words[0155]=agc_negate(m->words[0155]);m->words[0137]=m->words[0136];m->words[0136]=variant(mission,013702,013701);}m->words[2]=sign<0?variant(mission,06743,06712):3u;a=agc_add_register(agc_extend(057777),agc_extend(m->words[0154]));cl=agc_classify(agc_correct(a));if(cl==AGC_POSITIVE){m->words[0]=agc_diminished_abs(agc_correct(a));if(m->words[0]!=0){m->words[5]=variant(mission,03723,03722);return INVERSE_TRIG_ALARM_1301;}zero_answer(m,mission,0,1);return INVERSE_TRIG_DONE;}if(cl==AGC_MINUS_ZERO&&agc_classify(m->words[0155])!=AGC_NEGATIVE){zero_answer(m,mission,0,1);return INVERSE_TRIG_DONE;}original_high=m->words[0154];original_low=m->words[0155];subtract_from(m,020000);m->words[0]=agc_extend(m->words[0133]);m->words[1]=agc_extend(m->words[0134]);m->words[0133]=original_high;m->words[0134]=original_low;m->words[2]=variant(mission,03650,03647);m->words[5]=03343;return INVERSE_TRIG_OK;}
static void load(p66_preparation *s,p66_scale_scratch *sc,const apollo_overlay_state *m){uint8_t i;for(i=0;i<7u;++i)s->mpac[i]=m->words[0154u+i];s->mpac[7]=0;s->rate.registers.a=m->words[0];s->rate.registers.l=m->words[1];sc->mptemp=m->words[0135];sc->ovfind=m->words[0121];}
static void store(apollo_overlay_state *m,const p66_preparation *s,const p66_scale_scratch *sc){uint8_t i;for(i=0;i<7u;++i)m->words[0154u+i]=s->mpac[i];m->words[0]=s->rate.registers.a;m->words[1]=s->rate.registers.l;m->words[0135]=sc->mptemp;m->words[0121]=sc->ovfind;}
static void rounded_shift(p66_preparation *s,p66_scale_scratch *sc,uint8_t count){agc_register_pair r=agc_multiply(agc_extend((agc_word)(040000u>>count)),s->mpac[1]);agc_register a;agc_dp p;sc->mptemp=(agc_word)(040000u>>count);s->mpac[1]=agc_correct(r.a);a=agc_add_register(agc_extend(agc_correct(r.l)),agc_extend(agc_correct(r.l)));if(agc_overflow(a))s->mpac[1]=agc_add_word(s->mpac[1],agc_overflow(a)>0?1u:077776u);s->mpac[2]=0;r=agc_multiply(agc_extend(s->mpac[0]),sc->mptemp);s->mpac[0]=0;p.high=0;p.low=s->mpac[1];agc_double_add(&r,&p);s->mpac[0]=p.high;s->mpac[1]=p.low;s->rate.registers=r;}
enum inverse_trig_status inverse_trig_root(apollo_overlay_state *m,enum inverse_trig_mission mission){p66_preparation s={0};p66_scale_scratch sc;p66_elapsed_state e={0};p66_divide_scratch d={0};p66_norm_scratch n={0};enum p66_norm_result result;uint8_t count;if(!continuation(m,mission)||m->words[5]!=03343u)return INVERSE_TRIG_OUT_OF_SCOPE;load(&s,&sc,m);e.buf=m->words[0130];d.buf_low=m->words[0131];n.sr=m->words[021];n.cyl=m->words[022];result=p66_normalized_square_root(&s,&sc,&e,&d,&n);store(m,&s,&sc);m->words[0130]=e.buf;m->words[0131]=d.buf_low;m->words[021]=n.sr;m->words[022]=n.cyl;if(result==P66_NORM_ALARM_1302){m->words[5]=03402;return INVERSE_TRIG_ALARM_1302;}count=(uint8_t)sc.mptemp;s.rate.registers.a=count?(agc_register)(count-1u):0;if(count){rounded_shift(&s,&sc,count);m->words[2]=variant(mission,03720,03717);}store(m,&s,&sc);m->words[2]=3;m->words[5]=variant(mission,03652,03651);return INVERSE_TRIG_OK;}
enum inverse_trig_status inverse_trig_polynomial(apollo_overlay_state *m,enum inverse_trig_mission mission){p66_preparation s={0};p66_scale_scratch sc;agc_dp x,p;agc_register_pair r;uint8_t i;if(!continuation(m,mission)||m->words[5]!=variant(mission,03652,03651))return INVERSE_TRIG_OUT_OF_SCOPE;x.high=m->words[0133];x.low=m->words[0134];m->words[0133]=m->words[0154];m->words[0134]=m->words[0155];load(&s,&sc,m);s.mpac[0]=coefficient[7].high;s.mpac[1]=coefficient[7].low;m->words[0122]=x.high;m->words[0123]=x.low;m->words[0116]=0122;m->words[0141]=variant(mission,03677,03676);m->words[0117]=variant(mission,03672,03671);m->words[0140]=6;for(i=7;i>0;--i){(void)p66_scalar_product(&s,&sc,&x);r.a=agc_extend(coefficient[i-1u].high);r.l=agc_extend(coefficient[i-1u].low);p.high=s.mpac[0];p.low=s.mpac[1];agc_double_add(&r,&p);s.mpac[0]=p.high;s.mpac[1]=p.low;s.rate.registers=r;if(i>1u){--m->words[0140];m->words[0117]=(agc_word)(m->words[0117]-2u);}}s.rate.registers.a=0;store(m,&s,&sc);m->words[2]=0142;m->words[5]=variant(mission,03677,03676);return INVERSE_TRIG_OK;}
enum inverse_trig_status inverse_trig_finish(apollo_overlay_state *m,enum inverse_trig_mission mission){p66_preparation s={0};p66_scale_scratch sc;agc_dp factor;if(!continuation(m,mission)||m->words[5]!=variant(mission,03677,03676))return INVERSE_TRIG_OUT_OF_SCOPE;load(&s,&sc,m);factor.high=m->words[0133];factor.low=m->words[0134];m->words[0116]=0133;(void)p66_scalar_product(&s,&sc,&factor);store(m,&s,&sc);epilogue(m,mission,variant(mission,03702,03701));return INVERSE_TRIG_DONE;}

uint8_t inverse_trig_constant_read(enum inverse_trig_mission mission,uint16_t address,uint16_t *out){uint16_t first;if(out==0||(mission!=INVERSE_TRIG_LM&&mission!=INVERSE_TRIG_CM))return 0;first=variant(mission,01656,01655);if(address==first){*out=6;return 1;}if(address>first&&address<=first+16u){uint8_t index=(uint8_t)(address-first-1u);*out=(index&1u)?coefficient[index>>1].low:coefficient[index>>1].high;return 1;}if(address==variant(mission,01733,01730)){*out=077763;return 1;}return 0;}
